-- Generated from the bundled vocabulary dataset. Run schema.sql first.
on conflict (id) do update set word=excluded.word, v2=excluded.v2, v3=excluded.v3, meaning=excluded.meaning, part_of_speech=excluded.part_of_speech, example=excluded.example, example_id=excluded.example_id, level=excluded.level;
select setval(pg_get_serial_sequence('public.vocabulary','id'), (select coalesce(max(id),1) from public.vocabulary));
